  "quilt.py": """"Helpers for the quilt-along planner."""

_DAYS_PER_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def stitch_window(year, month):
    """Return the number of days in the given month of the given year."""
    if not 1 <= month <= 12:
        raise ValueError("month must be in 1..12")
    if month == 2 and year % 4 == 0:
        return 29
    return _DAYS_PER_MONTH[month - 1]
"
 },
 "spec": "stitch_window(year, month) returns the number of days in the given month of the given year, so the planner knows how long the stitching window for that month's block is. It raises ValueError when month is not in 1..12.",
 "reference": """"Helpers for the quilt-along planner."""

_DAYS_PER_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def stitch_window(year, month):
    """Return the number of days in the given month of the given year."""
    if not 1 <= month <= 12:
        raise ValueError("month must be in 1..12")
    if month == 2 and year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        return 29
    return _DAYS_PER_MONTH[month - 1]
",
 "test": "import calendar
import random
from quilt import stitch_window

r = random.Random(2024)
for _ in range(300):
    y = r.randint(1, 9999)
    m = r.randint(1, 12)
    got = stitch_window(y, m)
    want = calendar.monthrange(y, m)[1]
    assert got == want, (y, m, got, want)

for y in (1600, 1700, 1900, 2000, 2023, 2024, 2100, 2400):
    for m in range(1, 13):
        got = stitch_window(y, m)
        want = calendar.monthrange(y, m)[1]
        assert got == want, (y, m, got, want)

assert stitch_window(1900, 2) == 28
assert stitch_window(2000, 2) == 29
assert stitch_window(2100, 2) == 28
assert stitch_window(2024, 2) == 29
assert stitch_window(2023, 2) == 28

for bad in (0, 13, -1):
    try:
        stitch_window(2024, bad)
    except ValueError:
        pass
    else:
        raise AssertionError("month %r should raise ValueError" % (bad,))
"
}

