    "solution.py": "def refills_remaining(label, default=0):
    if not isinstance(label, str):
        return default
    if label == '':
        return default
    s = label.strip()
    if ':' in s:
        num = s.split(':')[-1].strip()
    else:
        num = s.split()[0]
    try:
        return int(num)
    except ValueError:
        return default
