{"name": "t_deposit_csv_quoting", "entry": "deposits.py", "files": {"deposits.py": "import csv

HEADER = ['tenant', 'amount']


def add_deposit(path, tenant, amount):
    try:
        with open(path, encoding='utf-8') as f:
            has_header = any(True for _ in f)
    except FileNotFoundError:
        has_header = False
    with open(path, 'a', encoding='utf-8') as f:
        if not has_header:
            f.write('tenant,amount\n')
        f.write(f'{tenant},{amount}\n')


def list_deposits(path):
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rows = [row for row in csv.reader(f)]
    except FileNotFoundError:
        return []
    if not rows:
        return []
    return [(row[0], float(row[1])) for row in rows[1:] if row]
