{
 "name": "t_password_grade_rules",
 "entry": "solution.py",
 "files": {
  "solution.py": "def password_grade(pw, default="invalid"):
    if pw is None:
        return default
    if not pw:
        return default
    s = pw.strip()
    score = 0
    if len(s) >= 8:
        score += 1
    if any(c.islower() for c in s):
        score += 1
    if any(c.isupper() for c in s):
        score += 1
    if any(c.isdigit() for c in s):
        score += 1
    if any(not c.isalnum() for c in s):
        score += 1
    if score >= 5:
        return "strong"
    if score >= 3:
        return "medium"
    return "weak"
"
 },
 "spec": "password_grade(pw, default='invalid') returns 'weak', 'medium' or 'strong' from a password's length and mix of lowercase, uppercase, digits and symbols; it returns default for None, empty string or whitespace-only string and raises TypeError for any other non-string value.",
 "reference": "def password_grade(pw, default="invalid"):
    if pw is None:
        return default
    if not isinstance(pw, str):
        raise TypeError("password must be a string")
    s = pw.strip()
    if not s:
        return default
    score = 0
    if len(s) >= 8:
        score += 1
    if any(c.islower() for c in s):
        score += 1
    if any(c.isupper() for c in s):
        score += 1
    if any(c.isdigit() for c in s):
        score += 1
    if any(not c.isalnum() for c in s):
        score += 1
    if score >= 5:
        return "strong"
    if score >= 3:
        return "medium"
    return "weak"
",
 "test": "from solution import password_grade

assert password_grade("Abcd1234") == "medium"
assert password_grade("Abc1!xyz") == "strong"
assert password_grade("abcdef") == "weak"
assert password_grade("  Abcd1234  ") == "medium"

assert password_grade(None) == "invalid"
assert password_grade(None, "n/a") == "n/a"
assert password_grade("") == "invalid"
assert password_grade("   ") == "invalid"
assert password_grade("\t\n ") == "invalid"

for bad in (12345, b"abc", ["abc"], 3.14):
    try:
        password_grade(bad)
    except TypeError:
        pass
    else:
        assert False, "expected TypeError for %r" % (bad,)
"
}

