 "reference": "def normalize_coupon(code, default=None):
    if code is None:
        return default
    if not isinstance(code, str):
        raise TypeError("coupon code must be a string")
    cleaned = code.strip().upper().replace("-", "").replace(" ", "")
    if not cleaned:
        return default
    if not cleaned.isalnum():
        raise ValueError("malformed coupon code: %r" % code)
