    "solution.py": "def leg_minutes(text, default=0):
    s = text.strip()
    if not s or ' ' not in s:
        return default
    route, dur = s.rsplit(' ', 1)
    hours = 0
    minutes = 0
    if 'h' in dur:
        head, dur = dur.split('h', 1)
        try:
            hours = int(head)
        except ValueError:
            return default
    dur = dur.strip()
    if dur.endswith('m'):
        try:
            minutes = int(dur[:-1])
        except ValueError:
            return default
    elif dur:
        return default
    return hours * 60 + minutes
