{"name": "t_poker_hand_category", "entry": "solution.py", "files": {"solution.py": "_RANKS = "23456789TJQKA"


def hand_category(text, default=None):
    if text is None:
        return default
    cards = text.upper().split()
    if len(cards) != 5:
        return default
    ranks = sorted(_RANKS.index(card[0]) for card in cards)
    suits = {card[1] for card in cards}
    counts = sorted((ranks.count(r) for r in set(ranks)), reverse=True)
    flush = len(suits) == 1
    straight = ranks == list(range(ranks[0], ranks[0] + 5)) or ranks == [0, 1, 2, 3, 12]
    if straight and flush:
        return "straight flush"
    if counts[0] == 4:
        return "four of a kind"
    if counts == [3, 2]:
        return "full house"
    if flush:
        return "flush"
    if straight:
        return "straight"
    if counts[0] == 3:
        return "three of a kind"
    if counts[:2] == [2, 2]:
        return "two pair"
    if counts[0] == 2:
        return "one pair"
    return "high card"
"}, "spec": "hand_category(text, default=None) classifies a five-card poker hand written as whitespace-separated cards such as 'AS KS QS JS TS' (case-insensitive; ranks 23456789TJQKA, suits SHDC) as 'straight flush', 'four of a kind', 'full house', 'flush', 'straight', 'three of a kind', 'two pair', 'one pair' or 'high card'; it returns default for None, empty or whitespace-only text and for malformed text that is not exactly five valid cards, and it raises TypeError when text is not a string.", "reference": "_RANKS = "23456789TJQKA"
_SUITS = "SHDC"


def _valid_card(card):
    return len(card) == 2 and card[0] in _RANKS and card[1] in _SUITS


def hand_category(text, default=None):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    cards = text.upper().split()
    if len(cards) != 5 or not all(_valid_card(card) for card in cards):
        return default
    ranks = sorted(_RANKS.index(card[0]) for card in cards)
    suits = {card[1] for card in cards}
    counts = sorted((ranks.count(r) for r in set(ranks)), reverse=True)
    flush = len(suits) == 1
    straight = ranks == list(range(ranks[0], ranks[0] + 5)) or ranks == [0, 1, 2, 3, 12]
    if straight and flush:
        return "straight flush"
    if counts[0] == 4:
        return "four of a kind"
    if counts == [3, 2]:
        return "full house"
    if flush:
        return "flush"
    if straight:
        return "straight"
    if counts[0] == 3:
        return "three of a kind"
    if counts[:2] == [2, 2]:
        return "two pair"
    if counts[0] == 2:
        return "one pair"
    return "high card"
