def interval_seconds(text, default=None):
    if not isinstance(text, str):
        return default
    s = text.strip().lower()
    if not s:
        return default
    unit = s[-1]
    if unit in _UNITS:
        s, factor = s[:-1], _UNITS[unit]
    else:
        factor = 1
    try:
        return int(s) * factor
    except ValueError:
        return default
