 "reference": "def reference_rate(quotes):
    # Median of the usable quotes; None marks a missing quote.
    cleaned = []
    for q in quotes:
        if q is not None:
            cleaned.append(q)
    cleaned.sort()
    n = len(cleaned)
    if n == 0:
        raise ValueError('no usable quotes')
    mid = n // 2
    if n % 2 == 1:
        return cleaned[mid]
    return (cleaned[mid - 1] + cleaned[mid]) / 2
