    "solution.py": "def backoff_seconds(spec, default=None):
    if spec is None or spec == "":
        return default
    s = spec.strip().lower()
    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            return float(s[:-len(suffix)]) * factor
    return float(s)
"
  },
  "spec": "backoff_seconds(spec, default=None) converts a retry backoff string such as '2.5s', '500ms', '1m', '3' or ' 0.25 s ' into a delay in seconds (2.5, 0.5, 60.0, 3.0, 0.25); it returns default for None, an empty string, whitespace-only text or a malformed spec, and raises TypeError for a non-string spec.",
  "reference": "def backoff_seconds(spec, default=None):
    if spec is None:
        return default
    if not isinstance(spec, str):
        raise TypeError("backoff spec must be a string")
    s = spec.strip().lower()
    if not s:
        return default
    scale = 1.0
    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            scale = factor
            s = s[: -len(suffix)]
            break
    try:
        return float(s) * scale
    except ValueError:
        return default
