    """Count how often each whitespace-separated word of text occurs."""
    tally = {}
    word = ""
    for ch in text:
        if ch.isspace():
            if word:
                tally[word] = tally.get(word, 0) + 1
                word = ""
        else:
            word += ch
    return tally
