{
 "name": "t_justify_read_newlines",
 "entry": "aligner.py",
 "files": {
  "aligner.py": "def justify_line(words, width):
    if len(words) == 1:
        return words[0]
    total = sum(len(w) for w in words)
    gaps = len(words) - 1
    base, extra = divmod(width - total, gaps)
    parts = []
    for i, w in enumerate(words[:-1]):
        parts.append(w + ' ' * (base + (1 if i < extra else 0)))
    parts.append(words[-1])
    return ''.join(parts)


def wrap_justify(text, width):
    words = text.split()
    lines = []
    current = []
    size = 0
    for word in words:
        extra = len(word) + (1 if current else 0)
        if current and size + extra > width:
            lines.append(current)
            current = [word]
            size = len(word)
        else:
            current.append(word)
            size += extra
    if current:
        lines.append(current)
    out = []
    for i, chunk in enumerate(lines):
        if i == len(lines) - 1:
            out.append(' '.join(chunk))
        else:
            out.append(justify_line(chunk, width))
    return out


def save_justified(path, text, width):
    lines = wrap_justify(text, width)
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')
    return lines


def load_justified(path):
    try:
        with open(path, encoding='utf-8') as f:
            return f.read().split('\n')
    except FileNotFoundError:
        return []
"
 },
 "spec": "wrap_justify(text, width) rewraps text into lines of at most width characters, padding every line except the last with spaces so it is exactly width long. save_justified(path, text, width) writes those lines to path in the current folder, one per line with a newline after each (overwriting the file) and returns the list of lines; load_justified(path) returns the stored lines in order, or [] when the file is missing.",
 "reference": "def justify_line(words, width):
    if len(words) == 1:
        return words[0]
    total = sum(len(w) for w in words)
    gaps = len(words) - 1
    base, extra = divmod(width - total, gaps)
    parts = []
    for i, w in enumerate(words[:-1]):
        parts.append(w + ' ' * (base + (1 if i < extra else 0)))
    parts.append(words[-1])
    return ''.join(parts)


def wrap_justify(text, width):
    words = text.split()
    lines = []
    current = []
    size = 0
    for word in words:
        extra = len(word) + (1 if current else 0)
        if current and size + extra > width:
            lines.append(current)
            current = [word]
            size = len(word)
        else:
            current.append(word)
            size += extra
    if current:
        lines.append(current)
    out = []
    for i, chunk in enumerate(lines):
        if i == len(lines) - 1:
            out.append(' '.join(chunk))
        else:
            out.append(justify_line(chunk, width))
    return out


def save_justified(path, text, width):
    lines = wrap_justify(text, width)
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')
    return lines


def load_justified(path):
    try:
