 "reference": "import re

_NUMBER = re.compile(r'[-+]?\d*\.?\d+')


def harvest_yield(record, default=None):
    if record is None:
        return default
    if not isinstance(record, str):
        raise TypeError('record must be a string')
    match = _NUMBER.search(record)
    if match is None:
        return default
    return float(match.group())
",
