 "name": "t_mortgage_schedule_parse",
 "entry": "solution.py",
 "files": {
  "solution.py": "def monthly_payment_from_spec(spec, default=None):
    text = spec.strip()
    if not text:
        return default
    parts = text.split()
    if len(parts) != 3:
        raise ValueError("spec must have three fields")
    try:
        principal = float(parts[0])
        rate = float(parts[1])
        years = float(parts[2])
    except ValueError:
        raise ValueError("fields must be numbers")
    if principal <= 0 or rate < 0 or years <= 0:
        raise ValueError("values out of range")
    n = years * 12
    r = rate / 100 / 12
    if r == 0:
        return round(principal / n, 2)
    return round(principal * r / (1 - (1 + r) ** -n), 2)
"
 },
 "spec": "monthly_payment_from_spec(spec, default=None) parses a string of three numbers (principal, annual percentage rate, years) and returns the monthly payment rounded to 2 decimals; it returns default for None, empty or whitespace-only strings, and raises ValueError for any non-string type, malformed spec, or out-of-range values.",
 "reference": "def monthly_payment_from_spec(spec, default=None):
    if spec is None:
        return default
    if not isinstance(spec, str):
        raise ValueError("spec must be a string")
    text = spec.strip()
    if not text:
        return default
    parts = text.split()
    if len(parts) != 3:
        raise ValueError("spec must have three fields")
    try:
        principal = float(parts[0])
        rate = float(parts[1])
        years = float(parts[2])
    except ValueError:
        raise ValueError("fields must be numbers")
    if principal <= 0 or rate < 0 or years <= 0:
        raise ValueError("values out of range")
    n = years * 12
    r = rate / 100 / 12
    if r == 0:
        return round(principal / n, 2)
    return round(principal * r / (1 - (1 + r) ** -n), 2)
