{"name": "t_thumbnail_dimensions", "entry": "solution.py", "hidden_file": "lib/thumbkit.py", "files": {"lib/thumbkit.py": "def fit_within(width, height, max_side):
    if width <= 0 or height <= 0:
        return (0, 0)
    if width >= height:
        if width <= max_side:
            return (width, height)
        new_w = max_side
        new_h = max(1, int(height * max_side / width + 0.5))
        return (new_w, new_h)
    else:
        if height <= max_side:
            return (width, height)
        new_h = max_side
        new_w = max(1, int(width * max_side / height + 0.5))
        return (new_w, new_h)
