 "reference": "def parse_rental_minutes(raw, default=None):
    """Turn a bike-rental duration like '90m', '2h', '1.5 h' or '45'
    into a number of minutes."""
    if raw is None:
        return default
    if not isinstance(raw, str):
        raise TypeError('duration must be a string')
    text = raw.strip().lower()
    if not text:
        return default
    try:
        if text.endswith('h'):
            return float(text[:-1].strip()) * 60
        if text.endswith('m'):
            return float(text[:-1].strip())
        return float(text)
    except ValueError:
        return default
